// storeOverEmbedded is store.Store under the name of the field that
// storeOver embeds.
type storeOverEmbedded = store.Store

// storeOver is a subject of Store whose callables call spend and return
// their zero results. The planted defect of a ceiling passes a spend that
// exceeds the ceiling.
type storeOver struct {
	storeOverEmbedded
	spend func()
}

// Writer calls spend and returns its zero results.
func (o storeOver) Writer(shard.Scope, shard.NamespaceIncarnation, epoch.Epoch) (r0 store.Writer) {
	o.spend()
	return r0
}

// Outcome calls spend and returns its zero results.
func (o storeOver) Outcome(context.Context, shard.Scope, store.CommitID) (r0 store.Receipt, r1 bool, r2 error) {
	o.spend()
	return r0, r1, r2
}

// Campaign calls spend and returns its zero results.
func (o storeOver) Campaign(context.Context, shard.Scope) (r0 store.Leadership, r1 error) {
	o.spend()
	return r0, r1
}

// Limits calls spend and returns its zero results.
func (o storeOver) Limits(shard.Scope) (r0 store.Limits) {
	o.spend()
	return r0
}

// Fits calls spend and returns its zero results.
func (o storeOver) Fits(shard.Scope, *store.Mutation) (r0 error) {
	o.spend()
	return r0
}

// Close calls spend and returns its zero results.
func (o storeOver) Close() (r0 error) {
	o.spend()
	return r0
}

// Head calls spend and returns its zero results.
func (o storeOver) Head(context.Context, shard.Scope) (r0 store.Head, r1 error) {
	o.spend()
	return r0, r1
}

// Read calls spend and returns its zero results.
func (o storeOver) Read(
	context.Context,
	shard.Scope,
	shard.NamespaceIncarnation,
	store.Query,
	page.Page,
) (r0 store.State, r1 page.Cursor[shard.Placement], r2 error) {
	o.spend()
	return r0, r1, r2
}

// Watch calls spend and returns its zero results.
func (o storeOver) Watch(
	context.Context,
	shard.Scope,
	shard.NamespaceIncarnation,
	epoch.Epoch,
	shard.NodeID,
) (r0 iter.Seq2[store.Event, error]) {
	o.spend()
	return r0
}

// newStoreOver returns the planted defect of a ceiling of Store, whose
// callables call spend.
func newStoreOver(_ *StoreHandle, spend func()) store.Store {
	return storeOver{spend: spend}
}

